1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Rejects a create request that is missing or blank in any required owner field, before
14	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
15	 */
16	public class ValidateOwnerFields {
17	
18	    /** A syntactically valid address: local-part@domain with a dotted domain, no spaces. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
20	
21	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
22	            throws OwnerFieldsInvalidException {
23	        List<String> errors = new ArrayList<>();
24	        checkRequired("firstName", request.getFirstName(), errors);
25	        checkRequired("lastName", request.getLastName(), errors);
26	        checkRequired("address", request.getAddress(), errors);
27	        checkRequired("city", request.getCity(), errors);
28	        checkRequired("telephone", request.getTelephone(), errors);
29	        normalizeTelephone(request, errors);
30	        normalizeEmail(request, errors);
31	        if (!errors.isEmpty()) {
32	            throw new OwnerFieldsInvalidException(errors);
33	        }
34	        validated.set(request);
35	    }
36	
37	    private static void checkRequired(String field, String value, List<String> errors) {
38	        if (value == null || value.isBlank()) {
39	            errors.add(field);
40	        }
41	    }
42	
43	    /**
44	     * Normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the
45	     * result back on the request so later steps persist and return it. A value that
46	     * cannot form a valid E.164 number is a 400 (adds a "telephone" error).
47	     */
48	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
49	        String telephone = request.getTelephone();
50	        if (telephone == null) {
51	            return;
52	        }
53	        String e164 = TelephoneE164.toE164(telephone);
54	        if (e164 != null) {
55	            request.setTelephone(e164);
56	        }
57	        else if (!errors.contains("telephone")) {
58	            errors.add("telephone");
59	        }
60	    }
61	
62	    /**
63	     * Email is optional. When present (non-blank) it must be a syntactically valid address;
64	     * an invalid value is a 400 (adds an "email" error). A valid value is stored lower-cased
65	     * back on the request so later steps persist and return it lower-cased.
66	     */
67	    private static void normalizeEmail(OwnerFieldsDto request, List<String> errors) {
68	        String email = request.getEmail();
69	        if (email == null || email.isBlank()) {
70	            return;
71	        }
72	        String trimmed = email.trim();
73	        if (EMAIL.matcher(trimmed).matches()) {
74	            request.setEmail(trimmed.toLowerCase());
75	        }
76	        else if (!errors.contains("email")) {
77	            errors.add("email");
78	        }
79	    }
80	}
