1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInUseException;
8	
9	/**
10	 * Rejects a create request whose telephone is already used by any other owner. Runs
11	 * after {@link ValidateOwnerFields} has normalized the telephone to E.164, and before
12	 * {@link BuildOwner}, so a duplicate is a 409 rather than a persisted record. Duplicates
13	 * are detected by comparing E.164 values.
14	 */
15	public class CheckOwnerTelephoneUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws OwnerTelephoneInUseException {
19	        String telephone = TelephoneE164.toE164(request.getTelephone());
20	        if (telephone == null) {
21	            return;
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (telephone.equals(TelephoneE164.toE164(existing.getTelephone()))) {
25	                throw new OwnerTelephoneInUseException(request.getTelephone());
26	            }
27	        }
28	    }
29	}
