3	/**
4	 * Normalizes a telephone number to E.164 form.
5	 *
6	 * <p>Spaces, dashes and brackets are stripped. A value that already carries a leading
7	 * {@code '+'} keeps its country code as given; otherwise country code {@code +61} is
8	 * assumed and a single leading {@code '0'} is dropped from the national digits. The
9	 * result must contain 8 to 15 digits after the {@code '+'}; anything else is not a
10	 * valid E.164 number.
11	 *
12	 * <p>For example {@code "0412 345 678"} becomes {@code "+61412345678"} and
13	 * {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
14	 */
15	final class TelephoneE164 {
16	
17	    private TelephoneE164() {
18	    }
19	
20	    /**
21	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid
22	     * E.164 number (including a {@code null} input).
23	     */
24	    static String toE164(String raw) {
25	        if (raw == null) {
26	            return null;
27	        }
28	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
29	        if (cleaned.isEmpty()) {
30	            return null;
31	        }
32	        String digits;
33	        if (cleaned.charAt(0) == '+') {
34	            digits = cleaned.substring(1);
35	        }
36	        else {
37	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
38	            digits = "61" + national;
39	        }
40	        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
41	            return null;
42	        }
43	        if (digits.length() < 8 || digits.length() > 15) {
44	            return null;
45	        }
46	        return "+" + digits;
47	    }
48	}
